"""The whole Cadent schema. User-owned rows carry user_id; SI units are named in the column."""

import uuid
from collections.abc import Iterable
from datetime import date, datetime
from typing import Any

from sqlalchemy import (
    CheckConstraint,
    DateTime,
    ForeignKey,
    Index,
    MetaData,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

from cadent_core.models import RunType, Severity

# Stable constraint names, so autogenerated migrations are deterministic.
NAMING = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


def one_of(column: str, values: Iterable[str]) -> CheckConstraint:
    """A text column limited to fixed values: text + CHECK, easier to migrate than an enum."""
    allowed = ", ".join(f"'{v}'" for v in values)
    return CheckConstraint(f"{column} IN ({allowed})", name=column)


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING)
    type_annotation_map = {  # noqa: RUF012 (SQLAlchemy reads this class attribute)
        datetime: DateTime(timezone=True),
        dict[str, Any]: JSONB,
        list[str]: ARRAY(Text),
        str: Text,
    }


class Row:
    id: Mapped[uuid.UUID] = mapped_column(primary_key=True, default=uuid.uuid4)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())


class UserOwned(Row):
    user_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("users.id", ondelete="CASCADE"), index=True
    )


class User(Row, Base):
    __tablename__ = "users"
    __table_args__ = (
        UniqueConstraint("email"),
        CheckConstraint("email = lower(email)", name="email_lowercase"),
        one_of("role", ["owner", "user"]),
    )

    email: Mapped[str]
    password_hash: Mapped[str]
    timezone: Mapped[str]
    role: Mapped[str]


class UserProfile(UserOwned, Base):
    __tablename__ = "user_profiles"
    __table_args__ = (UniqueConstraint("user_id"), one_of("units", ["metric", "imperial"]))

    birth_year: Mapped[int | None]
    sex: Mapped[str | None]
    max_hr: Mapped[int | None]
    resting_hr: Mapped[int | None]
    units: Mapped[str] = mapped_column(server_default="metric")
    intake_completed_at: Mapped[datetime | None]


class DataSourceAccount(UserOwned, Base):
    __tablename__ = "data_source_accounts"
    __table_args__ = (
        UniqueConstraint("user_id", "provider"),
        one_of("provider", ["garmin"]),
        one_of("status", ["active", "needs_reauth", "disabled"]),
    )

    provider: Mapped[str]
    encrypted_tokens: Mapped[bytes | None]
    status: Mapped[str] = mapped_column(server_default="active")
    last_sync_at: Mapped[datetime | None]
    last_error: Mapped[str | None]


class Activity(UserOwned, Base):
    __tablename__ = "activities"
    __table_args__ = (
        UniqueConstraint("user_id", "provider", "source_id"),
        Index(None, "user_id", "local_date"),
    )

    data_source_account_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("data_source_accounts.id", ondelete="CASCADE")
    )
    provider: Mapped[str]
    source_id: Mapped[str]
    started_at: Mapped[datetime]
    local_date: Mapped[date]
    type: Mapped[str]
    distance_m: Mapped[int]
    duration_s: Mapped[int]
    moving_s: Mapped[int | None]
    avg_hr: Mapped[int | None]
    max_hr: Mapped[int | None]
    avg_cadence: Mapped[float | None]
    elevation_gain_m: Mapped[float | None]
    raw: Mapped[dict[str, Any]]


class ActivityLap(UserOwned, Base):
    __tablename__ = "activity_laps"
    __table_args__ = (UniqueConstraint("activity_id", "index"),)

    activity_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("activities.id", ondelete="CASCADE"))
    index: Mapped[int]
    distance_m: Mapped[int]
    duration_s: Mapped[int]
    avg_hr: Mapped[int | None]
    avg_pace_s_per_km: Mapped[float | None]


class DailyRecovery(UserOwned, Base):
    __tablename__ = "daily_recovery"
    __table_args__ = (UniqueConstraint("user_id", "date"),)

    date: Mapped[date]
    hrv_overnight_ms: Mapped[int | None]
    hrv_status: Mapped[str | None]
    sleep_s: Mapped[int | None]
    sleep_score: Mapped[int | None]
    resting_hr: Mapped[int | None]
    body_battery: Mapped[int | None]


class Plan(UserOwned, Base):
    __tablename__ = "plans"
    __table_args__ = (
        one_of("source", ["imported", "generated", "ai_draft"]),
        one_of("status", ["draft", "active", "archived"]),
        Index(
            "uq_plans_one_active",
            "user_id",
            unique=True,
            postgresql_where=text("status = 'active'"),
        ),
    )

    name: Mapped[str]
    race_date: Mapped[date | None]
    race_distance_m: Mapped[int | None]
    source: Mapped[str]
    status: Mapped[str] = mapped_column(server_default="draft")
    accepted_warnings: Mapped[dict[str, Any]] = mapped_column(server_default=text("'{}'::jsonb"))


class PlanWeek(UserOwned, Base):
    __tablename__ = "plan_weeks"
    __table_args__ = (UniqueConstraint("plan_id", "index"),)

    plan_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("plans.id", ondelete="CASCADE"))
    index: Mapped[int]
    phase: Mapped[str | None]
    is_cutback: Mapped[bool] = mapped_column(server_default=text("false"))
    target_distance_m: Mapped[int | None]


class Session(UserOwned, Base):
    """A planned entry in a plan (glossary: Session)."""

    __tablename__ = "sessions"
    __table_args__ = (one_of("type", list(RunType)), Index(None, "user_id", "date"))

    plan_week_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("plan_weeks.id", ondelete="CASCADE"))
    date: Mapped[date]
    type: Mapped[str]
    distance_m: Mapped[int]
    pace_min_s: Mapped[int | None]
    pace_max_s: Mapped[int | None]
    hr_zone: Mapped[int | None]
    notes: Mapped[str | None]


class RunMatch(UserOwned, Base):
    __tablename__ = "run_matches"
    __table_args__ = (
        UniqueConstraint("session_id"),
        UniqueConstraint("activity_id"),
        one_of("match_method", ["auto", "manual"]),
    )

    session_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("sessions.id", ondelete="CASCADE"))
    activity_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("activities.id", ondelete="CASCADE"))
    match_method: Mapped[str]


class Checkin(UserOwned, Base):
    __tablename__ = "checkins"
    __table_args__ = (
        UniqueConstraint("activity_id"),
        CheckConstraint("rpe BETWEEN 1 AND 10", name="rpe"),
        CheckConstraint("soreness BETWEEN 0 AND 10", name="soreness"),
    )

    activity_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("activities.id", ondelete="CASCADE"))
    rpe: Mapped[int | None]
    soreness: Mapped[int | None]
    pain_flag: Mapped[bool] = mapped_column(server_default=text("false"))
    pain_location: Mapped[str | None]
    notes: Mapped[str | None]


class RuleFinding(UserOwned, Base):
    """A Finding the rules engine reported for a plan."""

    __tablename__ = "rule_findings"
    __table_args__ = (one_of("severity", list(Severity)),)

    plan_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("plans.id", ondelete="CASCADE"), index=True
    )
    week_index: Mapped[int]
    rule_code: Mapped[str]
    severity: Mapped[str]
    day: Mapped[date]
    message: Mapped[str]
    accepted: Mapped[bool] = mapped_column(server_default=text("false"))


class OAuthClient(Row, Base):
    """A registered OAuth client. No user_id: clients register before anyone signs in (ADR 009)."""

    __tablename__ = "oauth_clients"
    __table_args__ = (UniqueConstraint("client_id"),)

    client_id: Mapped[str]
    redirect_uris: Mapped[list[str]]
    metadata_: Mapped[dict[str, Any]] = mapped_column("metadata")


class OAuthCode(UserOwned, Base):
    """A single-use authorization code, stored hashed (ADR 009)."""

    __tablename__ = "oauth_codes"
    __table_args__ = (UniqueConstraint("code_hash"),)

    code_hash: Mapped[str]
    client_id: Mapped[str] = mapped_column(
        ForeignKey("oauth_clients.client_id", ondelete="CASCADE")
    )
    redirect_uri: Mapped[str]
    code_challenge: Mapped[str]
    scopes: Mapped[list[str]]
    resource: Mapped[str | None]
    expires_at: Mapped[datetime]
    used_at: Mapped[datetime | None]


class OAuthToken(UserOwned, Base):
    """An access or refresh token, stored hashed; refresh tokens rotate (ADR 009)."""

    __tablename__ = "oauth_tokens"
    __table_args__ = (UniqueConstraint("token_hash"), one_of("kind", ["access", "refresh"]))

    token_hash: Mapped[str]
    kind: Mapped[str]
    client_id: Mapped[str] = mapped_column(
        ForeignKey("oauth_clients.client_id", ondelete="CASCADE")
    )
    scopes: Mapped[list[str]]
    resource: Mapped[str | None]
    expires_at: Mapped[datetime]
    revoked_at: Mapped[datetime | None]
